'use strict';
let user=null, products=[], cart={}, editing=null;
const view=document.querySelector('#view'), nav=document.querySelector('#navigation');
const adminPath=new URLSearchParams(location.search).get('portal')==='admin';
const deliveryPath=new URLSearchParams(location.search).get('portal')==='delivery';
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(n/100);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const message=s=>document.querySelector('#message').textContent=s;
const seed=[
{id:1,name:'Everyday Pro Laptop',category:'Laptop',description:'15.6-inch display · 16GB RAM · 512GB SSD. Sample product.',price_paise:5499900,stock:6,image_url:'',active:1},
{id:2,name:'Studio Wireless Headphones',category:'Headphone',description:'Noise cancellation · 40-hour battery · soft ear cushions.',price_paise:399900,stock:15,image_url:'',active:1},
{id:3,name:'Creator USB Microphone',category:'Microphone',description:'Clear vocals for streaming, podcasts, and online classes.',price_paise:249900,stock:8,image_url:'',active:1},
{id:4,name:'Mirrorless Creator Camera',category:'Camera',description:'4K video · interchangeable lens · compact creator kit.',price_paise:6299900,stock:3,image_url:'',active:1}
];
let state=JSON.parse(localStorage.getItem('electroshop-direct-preview-v1')||'null')||{products:seed,orders:[]};
const categories=['Laptop','Charger','Camera','Headphone','Speaker','Microphone','Other'];
const categoryLabels={Laptop:'Laptops',Charger:'Chargers',Camera:'Cameras',Headphone:'Headphones',Speaker:'Speakers',Microphone:'Microphones',Other:'Other'};
const icons={Laptop:'💻',Charger:'🔌',Camera:'📷',Headphone:'🎧',Speaker:'🔊',Microphone:'🎙️',Other:'📦'};
const extraProducts=[
['Dell Inspiron 15','Laptop','Dell',49999,7],['HP Pavilion','Laptop','HP',59999,4],['Lenovo IdeaPad Slim','Laptop','Lenovo',42999,6],
['Samsung 25W USB-C Charger','Charger','Samsung',1299,20],['Anker 65W GaN Charger','Charger','Anker',3499,12],['Apple 20W USB-C Adapter','Charger','Apple',1899,10],
['Sony Alpha Camera Kit','Camera','Sony',72999,3],['Nikon Creator Camera','Camera','Nikon',68999,2],
['Sony Wireless Headphones','Headphone','Sony',8999,9],['boAt Rockerz Headphones','Headphone','boAt',1999,18],
['JBL Portable Speaker','Speaker','JBL',4499,10],['boAt Bluetooth Speaker','Speaker','boAt',1499,15],['Sony Wireless Speaker','Speaker','Sony',6999,5]
];
if(!state.catalogVersion){
state.products.forEach(p=>p.brand=p.brand||({Laptop:'ASUS',Headphone:'JBL',Microphone:'Maono',Camera:'Canon'})[p.category]||'Other');
extraProducts.forEach((a,i)=>state.products.push({id:100+i,name:a[0],category:a[1],brand:a[2],price_paise:a[3]*100,stock:a[4],description:'Sample product for preview. Replace with your shop’s product details.',image_url:'',active:1}));
state.catalogVersion=2;localStorage.setItem('electroshop-direct-preview-v1',JSON.stringify(state));
}
const save=()=>{try{localStorage.setItem('electroshop-direct-preview-v1',JSON.stringify(state));}catch{state=JSON.parse(localStorage.getItem('electroshop-direct-preview-v1'));throw Error('Browser storage is full. Use a smaller photo or remove an unused photo.');}};

function customerKey(){return user?.email.toLowerCase()||'guest';}
function savedData(){state.customers??={};return state.customers[customerKey()]??=( {wishlist:[],later:[],cart:{}} );}
function restoreCart(){cart={...savedData().cart};}
function saveCart(){savedData().cart={...cart};save();navigation();}
function mergeGuest(){const guest=state.customers?.guest;if(!guest||!user)return;const target=savedData();target.wishlist=[...new Set([...target.wishlist,...guest.wishlist])];target.later=[...new Set([...target.later,...guest.later])];for(const [id,q] of Object.entries(guest.cart)){const p=state.products.find(p=>p.id===+id&&p.active);if(p)target.cart[id]=Math.min(p.stock,(target.cart[id]||0)+q);}delete state.customers.guest;save();}
function toggleWish(id){const data=savedData(),has=data.wishlist.includes(+id);data.wishlist=has?data.wishlist.filter(x=>x!==+id):[...data.wishlist,+id];save();navigation();return !has;}
function addItem(id){const p=state.products.find(p=>p.id===+id&&p.active);if(!p||p.stock<1)throw Error('This item is currently unavailable.');if((cart[id]||0)>=p.stock)throw Error('Stock limit reached');cart[id]=(cart[id]||0)+1;saveCart();message(p.name+' added to cart');}
function itemVisual(p){return p.image_url?`<img src="${esc(p.image_url)}" alt="${esc(p.name)}">`:`<span aria-hidden="true">${icons[p.category]||'📦'}</span>`;}

state.reviews??=[];state.returns??=[];
function returnLabel(item){return item.returnable?`Returnable within ${item.return_days||7} days of delivery`:'Not returnable';}
function ratingSummary(id){const r=(state.reviews||[]).filter(r=>r.product_id===+id);return r.length?`${(r.reduce((n,r)=>n+r.rating,0)/r.length).toFixed(1)} ★ (${r.length} ${r.length===1?'review':'reviews'})`:'No reviews yet';}
function canReturn(order,item){return order.status==='Delivered'&&item.returnable&&order.delivered_at&&Date.now()/1000<=order.delivered_at+(item.return_days||7)*86400;}
async function api(path,method='GET',body){
if(path==='/auth/me'){user={email:deliveryPath?'delivery@demo.com':adminPath?'owner@demo.com':'customer@demo.com',role:deliveryPath?'delivery':adminPath?'admin':'customer'};return user;}
if(path==='/auth/request-otp'){sessionStorage.setItem('demoEmail',body.email);return {message:'Demo code: 123456. No email is sent in this preview.'};}
if(path==='/auth/verify-otp'){if(body.code!=='123456')throw Error('Use the demo OTP: 123456');const u={email:body.email,role:body.email.toLowerCase()==='owner@demo.com'?'admin':body.email.toLowerCase()==='delivery@demo.com'?'delivery':'customer'};sessionStorage.setItem('demoUser',JSON.stringify(u));return u;}
if(path==='/auth/logout'){sessionStorage.removeItem('demoUser');return {};}
if(path==='/products')return state.products.filter(p=>p.active);
if(path.startsWith('/reviews/')&&method==='GET')return (state.reviews||[]).filter(r=>r.product_id===+path.split('/').pop()).map(({email,...r})=>r);
if(!user)throw Error('Please log in');
if(path.startsWith('/admin/')&&user.role!=='admin')throw Error('Owner access required');
if(path.startsWith('/admin/products')&&['POST','PUT'].includes(method)&&body.returnable&&(!Number.isInteger(body.return_days)||body.return_days<1||body.return_days>30))throw Error('Set a return window between 1 and 30 days.');
if(path==='/admin/products'&&method==='POST'){const p={...body,id:Date.now(),active:1};state.products.push(p);save();return p;}
if(path.startsWith('/admin/products/')){const p=state.products.find(p=>p.id===+path.split('/').pop());if(!p)throw Error('Product not found');if(method==='DELETE')p.active=0;else Object.assign(p,body);save();return {};}
if(path==='/returns'&&method==='POST'){
 const order=state.orders.find(o=>o.id===body.order_id&&o.email.toLowerCase()===user.email.toLowerCase());const item=order?.items.find(i=>i.product_id===+body.product_id);
 if(!order||!item)throw Error('You can only return items from your own order.');
 if(!canReturn(order,item))throw Error('This item is not eligible for return, or its return window has closed.');
 if((state.returns||[]).some(r=>r.order_id===order.id&&r.product_id===item.product_id))throw Error('A return request already exists for this item.');
 if(!body.reason||body.reason.trim().length<5||body.reason.length>1000)throw Error('Describe the return reason in 5–1000 characters.');
 const r={id:'RETURN-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),order_id:order.id,product_id:item.product_id,name:item.name,quantity:item.quantity,email:user.email,status:'Requested',reason:body.reason.trim(),created:Date.now()/1000,notes:''};(state.returns??=[]).unshift(r);save();return r;
}
if(path.startsWith('/admin/returns/')&&method==='PUT'){
 const r=(state.returns||[]).find(r=>r.id===path.split('/').pop());if(!r)throw Error('Return request not found');
 const allowed={Requested:['Approved','Rejected'],Approved:['Received'],Rejected:[],Received:[]};if(!allowed[r.status].includes(body.status))throw Error('This return status change is not allowed.');
 if(!body.notes||body.notes.trim().length<3)throw Error('Add a short note for the customer.');
 if(body.status==='Received'){const p=state.products.find(p=>p.id===r.product_id);if(p)p.stock+=r.quantity;}
 r.status=body.status;r.notes=body.notes.trim().slice(0,1000);r.updated=Date.now()/1000;save();return r;
}
if(path==='/reviews'&&method==='POST'){
 const order=state.orders.find(o=>o.id===body.order_id&&o.email.toLowerCase()===user.email.toLowerCase()&&o.status==='Delivered');
 if(!order?.items.some(i=>i.product_id===+body.product_id))throw Error('Only customers with a delivered order for this product can review it.');
 if(!Number.isInteger(body.rating)||body.rating<1||body.rating>5)throw Error('Choose a rating from 1 to 5.');
 if(!body.text||body.text.trim().length<3||body.text.length>2000)throw Error('Write a review in 3–2000 characters.');
 if(body.photo&&(!/^data:image\/jpeg;base64,/.test(body.photo)||body.photo.length>800000))throw Error('Choose a smaller JPG, PNG, or WebP photo.');
 const reviews=state.reviews??=[],old=reviews.find(r=>r.product_id===+body.product_id&&r.email.toLowerCase()===user.email.toLowerCase());
 const review={id:old?.id||'REVIEW-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),product_id:+body.product_id,order_id:order.id,email:user.email,display_name:String(body.display_name||'Customer').trim().slice(0,60)||'Customer',rating:body.rating,text:body.text.trim(),photo:body.photo||'',created:old?.created||Date.now()/1000,updated:Date.now()/1000};
 if(old)Object.assign(old,review);else reviews.unshift(review);save();return {message:'Review published'};
}
if(path==='/orders'&&method==='POST'){
 const items=body.items.map(i=>{const p=state.products.find(p=>p.id===i.product_id&&p.active);if(!p||p.stock<i.quantity)throw Error('Insufficient stock. Refresh your cart.');return {...i,name:p.name,price_paise:p.price_paise,returnable:!!p.returnable,return_days:p.returnable?(p.return_days||7):0};});
 let total=items.reduce((s,i)=>s+i.price_paise*i.quantity,0);if(total<100000)total+=4900;
 const o={id:'DEMO-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,5).toUpperCase(),email:user.email,name:body.name,phone:body.phone,address:body.address,items,total_paise:total,status:'Placed',payment_method:body.payment_method||'COD',payment_status:body.payment_method==='Online demo'?'Simulated success — no money charged':'Pay on delivery',payment_reference:body.payment_reference||'',history:[{status:'Placed',note:'Order received. Waiting for owner confirmation.',at:Date.now()/1000,actor:'Customer'}],created:Date.now()/1000};
 items.forEach(i=>state.products.find(p=>p.id===i.product_id).stock-=i.quantity);state.orders.unshift(o);save();return o;
}
if(path==='/orders')return state.orders.filter(o=>o.email===user.email);
if(path==='/admin/orders')return state.orders;
if(path==='/delivery/orders'){if(user.role!=='delivery')throw Error('Delivery access required');return state.orders.filter(o=>o.assigned_to===user.email.toLowerCase()&&!['Placed','Cancelled'].includes(o.status));}
if(path.startsWith('/admin/orders/')||path.startsWith('/delivery/orders/')){
 const o=state.orders.find(o=>o.id===path.split('/').pop());if(!o)throw Error('Order not found');
 const isOwner=user.role==='admin';
 if(!isOwner&&(user.role!=='delivery'||o.assigned_to!==user.email.toLowerCase()))throw Error('This delivery is not assigned to you');
 if(o.status==='Placed'&&['assigned_to','courier','tracking','eta'].some(k=>k in body))throw Error('The owner must confirm this order before assigning or updating delivery.');
 if(o.status==='Placed'&&!isOwner)throw Error('Only the owner can confirm or reject a new order.');
 const allowed={Placed:['Confirmed','Cancelled'],Confirmed:['Shipped','Cancelled'],Shipped:['Out for delivery','Delivered','Delivery failed'], 'Out for delivery':['Delivered','Delivery failed'],'Delivery failed':['Out for delivery'],Delivered:[],Cancelled:[]};
 if(body.status&&body.status!==o.status){if(!allowed[o.status]?.includes(body.status)||(!isOwner&&!['Shipped','Out for delivery','Delivered','Delivery failed'].includes(body.status)))throw Error('This status change is not allowed');if(body.status==='Cancelled')o.items.forEach(i=>state.products.find(p=>p.id===i.product_id).stock+=i.quantity);if(body.status==='Delivered')o.delivered_at=Date.now()/1000;o.status=body.status;}
 if(isOwner&&'assigned_to' in body)o.assigned_to=body.assigned_to;
 if('courier' in body)o.courier=body.courier;
 if('tracking' in body)o.tracking=body.tracking;
 if('eta' in body)o.eta=body.eta;
 o.history??=[{status:'Placed',note:'Order received. Waiting for owner confirmation.',at:o.created,actor:'Customer'}];
 o.history.push({status:o.status,note:body.note||'Delivery information updated',at:Date.now()/1000,actor:isOwner?'Shop owner':'Delivery partner'});save();return {};
}
throw Error('Unknown demo action');
}
function action(fn){return async e=>{e?.preventDefault();const button=e?.submitter||e?.currentTarget;if(button?.tagName==='BUTTON')button.disabled=true;try{await fn(e);}catch(err){message(err.message);}finally{if(button?.tagName==='BUTTON')button.disabled=false;}};}
function navigation(){
 const isAdmin=adminPath&&user?.role==='admin',isDelivery=deliveryPath&&user?.role==='delivery',qty=Object.values(cart).reduce((a,b)=>a+b,0);
 nav.innerHTML=isDelivery?'<button id="orders">My deliveries</button><button id="navProfile" class="secondary">Profile</button><button id="logout" class="secondary">Re-enter portal</button>':isAdmin?`<button id="navShop" class="secondary">Products</button><button id="orders">Orders</button><button id="navStock" class="secondary">Stock</button><button id="logout" class="secondary">Re-enter portal</button>`:`<button id="navShop" class="secondary">Shop</button><button id="navWishlist" class="secondary">♡ Wishlist (${savedData().wishlist.length})</button><button id="navCart" class="secondary">Cart (${qty})</button><button id="orders" class="secondary">My Orders</button><button id="navProfile" class="secondary">Profile</button>${user?'<button id="logout" class="secondary">Re-enter portal</button>':'<button id="login">Log in</button>'}`;
 if(document.querySelector('#navShop'))document.querySelector('#navShop').onclick=action(shop);
 if(document.querySelector('#navProfile'))document.querySelector('#navProfile').onclick=()=>profileView();
 document.querySelector('#orders').onclick=action(async()=>{if(!user){message('Log in to see your orders.');login('orders');return;}await orders();});
 if(isAdmin)document.querySelector('#navStock').onclick=stockView;
 else if(!isDelivery){document.querySelector('#navWishlist').onclick=()=>collectionView('wishlist');document.querySelector('#navCart').onclick=action(async()=>{products=await api('/products');cartView();});}
 if(user)document.querySelector('#logout').onclick=action(async()=>{await api('/auth/logout','POST');user=null;restoreCart();navigation();await shop();});
 else document.querySelector('#login').onclick=()=>login();
}

function login(destination='shop'){
 user={email:deliveryPath?'delivery@demo.com':adminPath?'owner@demo.com':'customer@demo.com',role:deliveryPath?'delivery':adminPath?'admin':'customer'};
 restoreCart();navigation();
 if(destination==='profile')profileView();else if(destination==='orders'||deliveryPath)orders();else if(destination==='checkout')checkoutForm();else shop();
}

async function shop(){
 if(deliveryPath){if(!user||user.role!=='delivery'){login();return;}await orders();return;}
 products=await api('/products');
 if(adminPath){if(!user){login();return;}if(user.role!=='admin'){view.innerHTML='<div class="card"><h2>Owner access required</h2><p>Click Try owner login above to preview the owner portal.</p></div>';return;}}
 view.innerHTML=`<h2>${adminPath?'Manage your shop':'Find your next upgrade.'}</h2><p class="muted">${adminPath?'Add photos, set brands and prices, and manage your inventory.':'Explore electronics by category, brand, and budget.'}</p><div class="category-tabs" role="group" aria-label="Product categories"><button data-category="" class="selected">All items</button>${categories.filter(c=>c!=='Other').map(c=>`<button data-category="${c}" class="secondary">${icons[c]} ${categoryLabels[c]}</button>`).join('')}</div><div class="card filters"><label>Search<input id="search" placeholder="Search electronics…"></label><label>Company / Brand<select id="brand"><option value="">All companies</option>${[...new Set(products.map(p=>p.brand||'Other'))].sort().map(b=>`<option value="${esc(b)}">${esc(b)}</option>`).join('')}</select></label><label>Min price (₹)<input id="minPrice" type="number" min="0" placeholder="0"></label><label>Max price (₹)<input id="maxPrice" type="number" min="0" placeholder="Any price"></label><label>Sort by<select id="sort"><option value="featured">Featured</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option></select></label><button id="clearFilters" class="secondary">Clear filters</button></div><div class="row" style="justify-content:space-between;margin-bottom:20px"><span id="resultCount" class="muted" role="status"></span>${adminPath?'<button id="newProduct">＋ Add product</button>':'<button id="cart">View cart</button>'}</div><div id="catalog"></div>`;
 let category='';
 if(adminPath)document.querySelector('#newProduct').onclick=()=>productForm();else document.querySelector('#cart').onclick=cartView;
 const draw=()=>{
 const q=document.querySelector('#search').value.toLowerCase(),brand=document.querySelector('#brand').value,min=document.querySelector('#minPrice').value,max=document.querySelector('#maxPrice').value,sort=document.querySelector('#sort').value;
 const invalid=min!==''&&max!==''&&+min>+max;
 const filtered=products.filter(p=>(!category||p.category===category)&&(!brand||p.brand===brand)&&p.name.toLowerCase().includes(q)&&(min===''||p.price_paise>=+min*100)&&(max===''||p.price_paise<=+max*100));
 if(sort!=='featured')filtered.sort((a,b)=>sort==='low'?a.price_paise-b.price_paise:b.price_paise-a.price_paise);
 document.querySelector('#resultCount').textContent=invalid?'Minimum price must be less than maximum price.':`${filtered.length} product${filtered.length===1?'':'s'} found`;
 const card=p=>`<article class="card product-card"><div class="product-image">${p.image_url?`<img src="${esc(p.image_url)}" alt="${esc(p.name)}" loading="lazy">`:`<span aria-hidden="true">${icons[p.category]||'📦'}</span>`}</div><div class="row"><span class="brand-tag">${esc(p.brand||'Other')}</span><small>${esc(categoryLabels[p.category]||p.category)}</small></div><h3>${esc(p.name)}</h3><p class="muted description">${esc(p.description)}</p><p class="price">${money(p.price_paise)}</p><p class="muted">${p.stock} available</p><p class="policy-tag ${p.returnable?'return-yes':''}">${returnLabel(p)}</p><button class="review-link" data-view-reviews="${p.id}">${ratingSummary(p.id)} · View reviews</button>${adminPath?`<div class="row"><button data-edit="${p.id}">Edit product</button><button class="danger" data-delete="${p.id}">Remove</button></div>`:`<div class="row"><button data-add="${p.id}" ${p.stock?'':'disabled'}>${p.stock?'Add to cart':'Out of stock'}</button><button class="wish-button secondary" data-wish="${p.id}" aria-label="${savedData().wishlist.includes(p.id)?'Remove from':'Add to'} wishlist: ${esc(p.name)}" aria-pressed="${savedData().wishlist.includes(p.id)}">${savedData().wishlist.includes(p.id)?'♥ Saved':'♡ Save'}</button></div>`}</article>`;
 document.querySelector('#catalog').innerHTML=invalid?'<div class="card">Adjust your price range to see products.</div>':!filtered.length?'<div class="card"><h3>No matching products</h3><p>Try another company, category, or price range.</p></div>':category||sort!=='featured'?`<div class="grid">${filtered.map(card).join('')}</div>`:categories.map(c=>{const group=filtered.filter(p=>p.category===c);return group.length?`<section class="product-section"><h3 class="section-heading">${icons[c]} ${categoryLabels[c]} <small>${group.length} ${group.length===1?'item':'items'}</small></h3><div class="grid">${group.map(card).join('')}</div></section>`:'';}).join('');
 document.querySelectorAll('[data-view-reviews]').forEach(b=>b.onclick=action(()=>reviewsView(+b.dataset.viewReviews)));
 document.querySelectorAll('[data-add]').forEach(b=>b.onclick=action(()=>addItem(b.dataset.add)));
 document.querySelectorAll('[data-wish]').forEach(b=>b.onclick=action(()=>{const added=toggleWish(b.dataset.wish);message(added?'Added to your wishlist':'Removed from your wishlist');draw();}));
 document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>productForm(products.find(x=>x.id===+b.dataset.edit)));
 document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=action(async()=>{if(confirm('Remove this product from the shop?')){await api('/admin/products/'+b.dataset.delete,'DELETE');await shop();}}));
 };
 document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>{x.classList.toggle('selected',x===b);x.classList.toggle('secondary',x!==b);x.setAttribute('aria-pressed',String(x===b));});draw();});
 ['search','minPrice','maxPrice'].forEach(id=>document.getElementById(id).oninput=draw);
 ['brand','sort'].forEach(id=>document.getElementById(id).onchange=draw);
 document.querySelector('#clearFilters').onclick=()=>{['search','minPrice','maxPrice','brand'].forEach(id=>document.getElementById(id).value='');document.getElementById('sort').value='featured';document.querySelector('[data-category=""]').click();};draw();
}
async function compressPhoto(file){
 if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choose a JPG, PNG, or WebP image.');
 if(file.size>5*1024*1024)throw Error('Choose an image smaller than 5 MB.');
 const url=URL.createObjectURL(file);
 try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('This photo could not be opened.'));img.src=url;});const scale=Math.min(1,1000/img.width,1000/img.height),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',0.78);}finally{URL.revokeObjectURL(url);}
}
function productForm(p={}){
 editing=p.id;let photo=p.image_url||'',reading=false;
 view.innerHTML=`<div class="card"><h2>${p.id?'Edit':'Add'} product</h2><form id="productForm"><label>Product name<input name="name" maxlength="150" required value="${esc(p.name)}"></label><div class="form-row"><label>Category<select name="category">${categories.map(c=>`<option value="${c}" ${c===p.category?'selected':''}>${categoryLabels[c]}</option>`).join('')}</select></label><label>Company / Brand<input name="brand" maxlength="80" required placeholder="e.g. Dell, Sony, JBL" value="${esc(p.brand)}"></label></div><label>Description<textarea name="description" maxlength="4000">${esc(p.description)}</textarea></label><div class="form-row"><label>Price in rupees<input name="price" type="number" min="0.01" max="1000000" step="0.01" required value="${p.price_paise?p.price_paise/100:''}"></label><label>Stock<input name="stock" type="number" min="0" max="100000" required value="${p.stock??0}"></label></div><fieldset><legend>Return policy</legend><label>Can customers return this item?<select name="returnable" id="returnable"><option value="no" ${!p.returnable?'selected':''}>No — not returnable</option><option value="yes" ${p.returnable?'selected':''}>Yes — returnable after delivery</option></select></label><label id="returnDaysField">Return window (days after delivery)<input name="return_days" type="number" min="1" max="30" value="${p.return_days||7}"></label><small>The policy is shown before ordering and saved with the order.</small></fieldset><label>Upload product photo<input id="photoFile" type="file" accept="image/jpeg,image/png,image/webp"></label><small>JPG, PNG, or WebP · up to 5 MB. Photos in this demo are saved only in this browser.</small><div id="photoPreview" class="photo-preview"></div><button id="removePhoto" type="button" class="secondary">Remove photo</button><label style="margin-top:16px">Or paste an HTTPS image URL<input id="imageUrl" type="url" placeholder="https://…" value="${photo.startsWith('https://')?esc(photo):''}"></label><p id="photoStatus" role="status" class="muted"></p><div class="row"><button id="saveProduct">Save product</button><button id="back" type="button" class="secondary">Back</button></div></form></div>`;
 const preview=()=>{document.querySelector('#photoPreview').innerHTML=photo?`<img src="${esc(photo)}" alt="Product photo preview">`:'<span>No photo selected</span>';document.querySelector('#removePhoto').hidden=!photo;};preview();
 const toggleReturnDays=()=>{const enabled=document.querySelector('#returnable').value==='yes';document.querySelector('#returnDaysField').hidden=!enabled;document.querySelector('[name="return_days"]').disabled=!enabled;};document.querySelector('#returnable').onchange=toggleReturnDays;toggleReturnDays();
 document.querySelector('#photoFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;reading=true;document.querySelector('#saveProduct').disabled=true;try{photo=await compressPhoto(file);document.querySelector('#imageUrl').value='';preview();document.querySelector('#photoStatus').textContent='Photo ready. Click Save product to keep it.';}catch(err){document.querySelector('#photoStatus').textContent=err.message;e.target.value='';}finally{reading=false;document.querySelector('#saveProduct').disabled=false;}};
 document.querySelector('#imageUrl').onchange=e=>{const url=e.target.value.trim();if(url&&!url.startsWith('https://')){document.querySelector('#photoStatus').textContent='Image URLs must start with https://';return;}photo=url;document.querySelector('#photoFile').value='';preview();};
 document.querySelector('#removePhoto').onclick=()=>{photo='';document.querySelector('#photoFile').value='';document.querySelector('#imageUrl').value='';preview();};
 document.querySelector('#back').onclick=action(shop);
 document.querySelector('#productForm').onsubmit=action(async e=>{if(reading)throw Error('Please wait for the photo to finish.');const f=Object.fromEntries(new FormData(e.target));if(!f.name.trim()||!f.brand.trim())throw Error('Enter a product name and company.');await api('/admin/products'+(editing?'/'+editing:''),editing?'PUT':'POST',{name:f.name.trim(),brand:f.brand.trim(),category:f.category,description:f.description,price_paise:Math.round(Number(f.price)*100),stock:Number(f.stock),returnable:f.returnable==='yes',return_days:f.returnable==='yes'?Number(f.return_days):0,image_url:photo});message('Product saved with its photo and company');await shop();});
}

function cartView(){
 products=state.products.filter(p=>p.active);
 const items=Object.entries(cart).filter(([id,qty])=>qty>0&&products.some(p=>p.id===+id));
 const unavailable=Object.keys(cart).filter(id=>cart[id]>0&&!products.some(p=>p.id===+id));
 const subtotal=items.reduce((sum,[id,qty])=>sum+products.find(p=>p.id===+id).price_paise*qty,0),delivery=subtotal&&subtotal<100000?4900:0;
 view.innerHTML=`<h2>Your cart</h2><p class="muted">Buy now, or save items for another day.</p><div class="cart-layout"><div>${items.map(([id,qty])=>{const p=products.find(p=>p.id===+id);return `<article class="card basket-item"><div class="mini-image">${itemVisual(p)}</div><div><small>${esc(p.brand)}</small><h3>${esc(p.name)}</h3><p>${money(p.price_paise)} each · ${p.stock} in stock</p><p class="policy-tag">${returnLabel(p)}</p><div class="row"><button class="secondary" data-less="${id}" aria-label="Decrease quantity of ${esc(p.name)}">−</button><span>${qty}</span><button class="secondary" data-more="${id}" aria-label="Increase quantity of ${esc(p.name)}">+</button><button class="secondary" data-later="${id}">Save for later</button><button class="text-button" data-remove="${id}">Remove</button></div></div><strong>${money(p.price_paise*qty)}</strong></article>`;}).join('')||'<div class="card"><h3>Your cart is empty</h3><p>Browse your shop or move a saved item to the cart.</p></div>'}${unavailable.length?'<p class="muted">Unavailable products have been removed from your cart.</p>':''}</div><aside class="card order-summary"><h3>Order summary</h3><p class="summary-line"><span>Subtotal</span><strong>${money(subtotal)}</strong></p><p class="summary-line"><span>Delivery</span><strong>${money(delivery)}</strong></p><hr><p class="summary-line"><span>Total</span><strong>${money(subtotal+delivery)}</strong></p><p class="muted">Cash on delivery · Free delivery from ₹1,000</p>${items.length?'<button id="checkout">Proceed to checkout</button>':''}<button id="back" class="secondary">Continue shopping</button></aside></div><div class="row"><h3>Saved for later (${savedData().later.length})</h3><button id="viewLater" class="secondary">View saved items</button></div>`;
 unavailable.forEach(id=>delete cart[id]);if(unavailable.length)saveCart();
 document.querySelector('#back').onclick=action(shop);document.querySelector('#viewLater').onclick=()=>collectionView('later');
 document.querySelectorAll('[data-less]').forEach(b=>b.onclick=action(()=>{const id=b.dataset.less;if(--cart[id]<=0)delete cart[id];saveCart();cartView();}));
 document.querySelectorAll('[data-more]').forEach(b=>b.onclick=action(()=>{addItem(b.dataset.more);cartView();}));
 document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=action(()=>{delete cart[b.dataset.remove];saveCart();cartView();}));
 document.querySelectorAll('[data-later]').forEach(b=>b.onclick=action(()=>{const id=+b.dataset.later;const data=savedData();if(!data.later.includes(id))data.later.push(id);delete cart[id];saveCart();cartView();message('Item moved to Saved for later. It is not included in your total.');}));
 if(items.length)document.querySelector('#checkout').onclick=()=>{if(!user){login('checkout');message('Log in to complete your order. Your cart is saved.');return;}checkoutForm();};
}
function collectionView(kind='wishlist'){
 const data=savedData(),ids=data[kind],items=ids.map(id=>state.products.find(p=>p.id===id)).filter(Boolean);
 view.innerHTML=`<h2>${kind==='wishlist'?'Your wishlist':'Saved for later'}</h2><p class="muted">${kind==='wishlist'?'Keep your favourite products here. Saving an item does not reserve stock.':'Items you set aside from your cart. They are not included in checkout.'}</p><div class="category-tabs"><button id="wishlistTab" class="${kind==='wishlist'?'':'secondary'}">♡ Wishlist (${data.wishlist.length})</button><button id="laterTab" class="${kind==='later'?'':'secondary'}">Saved for later (${data.later.length})</button><button id="back" class="secondary">Continue shopping</button></div><div class="grid">${items.map(p=>`<article class="card product-card"><div class="product-image">${itemVisual(p)}</div><small>${esc(p.brand)}</small><h3>${esc(p.name)}</h3><p class="price">${money(p.price_paise)}</p><p class="muted">${!p.active?'No longer sold':p.stock?p.stock+' in stock':'Out of stock'}</p><div class="row"><button data-move="${p.id}" ${p.active&&p.stock?'':'disabled'}>${kind==='later'?'Move to cart':'Add to cart'}</button><button class="secondary" data-remove-saved="${p.id}">Remove</button></div></article>`).join('')||'<div class="card"><h3>Nothing saved yet</h3><p>Tap ♡ Save on a product, or Save for later in your cart.</p></div>'}</div>`;
 document.querySelector('#wishlistTab').onclick=()=>collectionView('wishlist');document.querySelector('#laterTab').onclick=()=>collectionView('later');document.querySelector('#back').onclick=action(shop);
 document.querySelectorAll('[data-move]').forEach(b=>b.onclick=action(()=>{const id=+b.dataset.move;addItem(id);if(kind==='later'){data.later=data.later.filter(x=>x!==id);save();}collectionView(kind);}));
 document.querySelectorAll('[data-remove-saved]').forEach(b=>b.onclick=action(()=>{data[kind]=data[kind].filter(id=>id!==+b.dataset.removeSaved);save();navigation();collectionView(kind);}));
}
function stockView(){
 const all=state.products.filter(p=>p.active),low=all.filter(p=>p.stock<=5);
 view.innerHTML=`<h2>Stock overview</h2><p class="muted">Products with five or fewer units need your attention.</p><div class="metric-grid"><div class="card"><small>Active products</small><strong>${all.length}</strong></div><div class="card"><small>Low stock (1–5)</small><strong>${low.filter(p=>p.stock>0).length}</strong></div><div class="card"><small>Out of stock</small><strong>${low.filter(p=>!p.stock).length}</strong></div></div>${low.map(p=>`<div class="card row"><strong>${esc(p.name)}</strong><span class="status-pill">${p.stock} left</span><button data-restock="${p.id}">Update stock</button></div>`).join('')||'<div class="card">All products have healthy stock levels.</div>'}`;
 document.querySelectorAll('[data-restock]').forEach(b=>b.onclick=()=>productForm(all.find(p=>p.id===+b.dataset.restock)));
}

function checkoutForm(draft={}){
 if(!user){login('checkout');return;}
 const data=savedData(),profile=data.profile||{},addresses=data.addresses||[];let selected=addresses.find(a=>a.id===data.defaultAddress)||addresses[0];
 view.innerHTML=`<div class="card"><h2>Checkout</h2><p class="notice">Your order will be sent to the owner for confirmation. Packing and delivery begin only after the owner accepts it.</p><p class="muted">Use a saved address or enter a new delivery address.</p><div class="card checkout-policy"><h3>Return policy for your items</h3>${Object.entries(cart).filter(([,q])=>q>0).map(([id])=>{const p=state.products.find(p=>p.id===+id);return p?`<p><strong>${esc(p.name)}</strong><br><span class="policy-tag">${returnLabel(p)}</span></p>`:'';}).join('')}</div><form id="checkoutForm">${addresses.length?`<label>Saved delivery address<select id="savedAddress"><option value="">Enter a different address</option>${addresses.map(a=>`<option value="${esc(a.id)}" ${a.id===selected?.id?'selected':''}>${esc(a.label)} — ${esc(a.line)}, ${esc(a.city)}</option>`).join('')}</select></label>`:''}<button id="manageAddresses" type="button" class="secondary">Manage saved addresses</button><label>Full name<input name="name" minlength="2" maxlength="120" required autocomplete="name" value="${esc(draft.name||selected?.name||profile.name)}"></label><label>Indian mobile number<input name="phone" type="tel" pattern="[6-9][0-9]{9}" required autocomplete="tel" value="${esc(draft.phone||selected?.phone||profile.phone)}"></label><label>Full address, city, state and PIN code<textarea name="address" minlength="10" maxlength="1000" required autocomplete="street-address">${draft.address?esc(draft.address):selected?esc(formatAddress(selected)):''}</textarea></label><fieldset><legend>Payment method</legend><label class="radio-label"><input type="radio" name="payment" value="COD" checked> Cash on delivery</label><label class="radio-label"><input type="radio" name="payment" value="Online demo"> Online payment preview · UPI / card / net banking</label></fieldset><p class="notice">Online payment here is a simulation. No money is collected. Never enter real card details or a UPI PIN in this demo.</p><button id="placeOrder">Submit order · Cash on delivery</button> <button id="back" type="button" class="secondary">Back to cart</button></form></div>`;
 document.querySelector('#manageAddresses').onclick=()=>profileView();
 if(addresses.length)document.querySelector('#savedAddress').onchange=e=>{selected=addresses.find(a=>a.id===e.target.value);document.querySelector('[name="name"]').value=selected?.name||profile.name||'';document.querySelector('[name="phone"]').value=selected?.phone||profile.phone||'';document.querySelector('[name="address"]').value=selected?formatAddress(selected):'';};
 document.querySelectorAll('[name="payment"]').forEach(r=>r.onchange=()=>document.querySelector('#placeOrder').textContent=r.value==='COD'?'Submit order · Cash on delivery':'Continue to payment preview');
 document.querySelector('#back').onclick=cartView;
 document.querySelector('#checkoutForm').onsubmit=action(async e=>{const f=Object.fromEntries(new FormData(e.target));const body={name:f.name,phone:f.phone,address:f.address,payment_method:f.payment,items:Object.entries(cart).filter(([,q])=>q>0).map(([id,quantity])=>({product_id:+id,quantity}))};if(body.payment_method==='Online demo'){paymentPreview(body);return;}await placeCheckout(body);});
}
async function placeCheckout(body){const result=await api('/orders','POST',body);cart={};saveCart();message('Order '+result.id+' submitted. Waiting for the owner to confirm. Total: '+money(result.total_paise));await orders();}
function paymentPreview(body){
 let subtotal=0;for(const i of body.items){const p=state.products.find(p=>p.id===i.product_id&&p.active);if(!p||p.stock<i.quantity)throw Error('Please refresh your cart: stock has changed.');subtotal+=p.price_paise*i.quantity;}const total=subtotal+(subtotal<100000?4900:0);
 view.innerHTML=`<section class="card payment-preview"><span class="status-pill">DEMO PAYMENT · NO REAL TRANSACTION</span><h2>Online checkout preview</h2><p class="price">${money(total)}</p><p>Choose a method to preview the payment result. This is not connected to a payment gateway.</p><label>Payment method<select id="demoPaymentMethod"><option>UPI</option><option>Debit / credit card</option><option>Net banking</option></select></label><p class="notice">No card number, bank details, OTP, or UPI PIN is required.</p><div class="row"><button id="demoPay">Simulate successful payment</button><button id="demoFail" class="secondary">Simulate failed payment</button><button id="cancelPay" class="secondary">Cancel</button></div></section>`;
 document.querySelector('#demoPay').onclick=action(async()=>{body.payment_reference='DEMO-PAY-'+Date.now().toString(36).toUpperCase();body.payment_channel=document.querySelector('#demoPaymentMethod').value;await placeCheckout(body);message('Simulated payment succeeded. Your order is awaiting owner confirmation. No money was charged.');});
 document.querySelector('#demoFail').onclick=()=>{checkoutForm(body);message('Simulated payment failed. No order was created and your cart is unchanged. You can retry or choose cash on delivery.');};
 document.querySelector('#cancelPay').onclick=()=>{checkoutForm(body);message('Payment preview cancelled. Your cart is unchanged.');};
}
function formatAddress(a){return `${a.line}, ${a.city}, ${a.state} ${a.pin}`;}
function profileView(){
 if(!user){login('profile');return;}
 const data=savedData(),profile=data.profile||{},addresses=data.addresses||[];
 view.innerHTML=`<h2>My profile</h2><p class="muted">Your personal details and delivery addresses. In this preview, details stay in this browser. Use sample information when testing.</p><div class="profile-layout"><section class="card"><h3>Personal details</h3><form id="profileForm"><label>Full name<input name="name" required minlength="2" maxlength="120" autocomplete="name" value="${esc(profile.name)}"></label><label>Email<input value="${esc(user.email)}" readonly type="email"></label><small>Email belongs to your login account.</small><label style="margin-top:15px">Mobile number<input name="phone" type="tel" pattern="[6-9][0-9]{9}" required autocomplete="tel" value="${esc(profile.phone)}"></label><button>Save personal details</button></form></section><section><div class="row" style="justify-content:space-between"><h3>Saved addresses</h3><button id="addAddress">＋ Add address</button></div>${addresses.map(a=>`<article class="card address-card"><div class="row"><h3>${esc(a.label)}</h3>${data.defaultAddress===a.id?'<span class="brand-tag">Default address</span>':''}</div><strong>${esc(a.name)}</strong><p>${esc(formatAddress(a))}</p><p>${esc(a.phone)}</p><div class="row"><button class="secondary" data-edit-address="${esc(a.id)}">Edit</button>${data.defaultAddress!==a.id?`<button class="secondary" data-default-address="${esc(a.id)}">Make default</button>`:''}<button class="text-button" data-delete-address="${esc(a.id)}">Remove</button></div></article>`).join('')||'<div class="card"><p>No saved addresses yet. Add one to make checkout faster.</p></div>'}</section></div><button id="profileShop" class="secondary">Back to shop</button><button id="profileCart" class="secondary">Go to cart</button>`;
 document.querySelector('#profileForm').onsubmit=action(e=>{const f=Object.fromEntries(new FormData(e.target));if(!f.name.trim())throw Error('Enter your name');data.profile={name:f.name.trim(),phone:f.phone};save();message('Personal details saved');});
 document.querySelector('#addAddress').onclick=()=>addressForm();document.querySelector('#profileShop').onclick=action(shop);document.querySelector('#profileCart').onclick=cartView;
 document.querySelectorAll('[data-edit-address]').forEach(b=>b.onclick=()=>addressForm(addresses.find(a=>a.id===b.dataset.editAddress)));
 document.querySelectorAll('[data-default-address]').forEach(b=>b.onclick=action(()=>{data.defaultAddress=b.dataset.defaultAddress;save();profileView();message('Default address updated');}));
 document.querySelectorAll('[data-delete-address]').forEach(b=>b.onclick=action(()=>{if(confirm('Remove this saved address?')){data.addresses=addresses.filter(a=>a.id!==b.dataset.deleteAddress);if(data.defaultAddress===b.dataset.deleteAddress)data.defaultAddress=data.addresses[0]?.id||'';save();profileView();message('Address removed');}}));
}
function addressForm(a={}){
 const profile=savedData().profile||{};
 view.innerHTML=`<section class="card"><h2>${a.id?'Edit':'Add'} address</h2><form id="addressForm"><label>Address label<input name="label" placeholder="Home, Work…" required maxlength="40" value="${esc(a.label||'Home')}"></label><label>Recipient name<input name="name" required minlength="2" maxlength="120" value="${esc(a.name||profile.name)}"></label><label>Mobile number<input name="phone" type="tel" pattern="[6-9][0-9]{9}" required value="${esc(a.phone||profile.phone)}"></label><label>House, street and locality<textarea name="line" minlength="5" maxlength="500" required>${esc(a.line)}</textarea></label><div class="form-row"><label>City<input name="city" required maxlength="80" value="${esc(a.city)}"></label><label>State<input name="state" required maxlength="80" value="${esc(a.state)}"></label></div><label>PIN code<input name="pin" inputmode="numeric" pattern="[1-9][0-9]{5}" maxlength="6" required value="${esc(a.pin)}"></label><button>Save address</button> <button id="cancelAddress" type="button" class="secondary">Cancel</button></form></section>`;
 document.querySelector('#cancelAddress').onclick=profileView;
 document.querySelector('#addressForm').onsubmit=action(e=>{const f=Object.fromEntries(new FormData(e.target));for(const k of ['label','name','line','city','state']){f[k]=f[k].trim();if(!f[k])throw Error('Please fill in all address fields.');}const data=savedData();data.addresses??=[];const record={...f,id:a.id||'ADDR-'+Date.now()};const index=data.addresses.findIndex(x=>x.id===record.id);if(index<0)data.addresses.push(record);else data.addresses[index]=record;if(!data.defaultAddress)data.defaultAddress=record.id;save();profileView();message('Address saved. You can choose it during checkout.');});
}

async function orders(){
 if(!user){login('orders');return;}
 const isAdmin=adminPath&&user.role==='admin',isDriver=deliveryPath&&user.role==='delivery',manager=isAdmin||isDriver;
 const list=await api(isAdmin?'/admin/orders':isDriver?'/delivery/orders':'/orders');
 const active=list.filter(o=>!['Delivered','Cancelled'].includes(o.status));
 view.innerHTML=`<h2>${isDriver?'My deliveries':isAdmin?'Manage orders & delivery':'My orders'}</h2><p class="muted">${isDriver?'Only deliveries assigned to your demo account appear here.':isAdmin?'Confirm new orders first. After confirmation, assign a delivery partner and manage dispatch.':'Track purchases, delivery updates, and payment status.'}</p><div class="metric-grid"><div class="card"><small>Total orders</small><strong>${list.length}</strong></div><div class="card"><small>In progress</small><strong>${active.length}</strong></div><div class="card"><small>Delivered</small><strong>${list.filter(o=>o.status==='Delivered').length}</strong></div></div><div class="card order-filters"><label>Find an order<input id="orderSearch" placeholder="Order ID, product${manager?', or customer':''}"></label><label>Status<select id="orderStatus"><option value="">All orders</option>${['Placed','Confirmed','Shipped','Out for delivery','Delivery failed','Delivered','Cancelled'].map(s=>`<option value="${s}">${s==='Placed'?'Awaiting owner confirmation':s}</option>`).join('')}</select></label><button id="back" class="secondary">${isDriver?'Refresh deliveries':'Back to shop'}</button></div><div id="orderList"></div>`;
 const draw=()=>{const q=document.querySelector('#orderSearch').value.toLowerCase(),status=document.querySelector('#orderStatus').value,filtered=list.filter(o=>(!status||o.status===status)&&[o.id,...o.items.map(i=>i.name),...(manager?[o.name,o.email,o.phone]:[])].some(x=>String(x).toLowerCase().includes(q)));
 document.querySelector('#orderList').innerHTML=filtered.map(o=>{
 const subtotal=o.items.reduce((sum,i)=>sum+i.price_paise*i.quantity,0),steps=['Placed','Confirmed','Shipped','Out for delivery','Delivered'],index=o.status==='Delivery failed'?3:steps.indexOf(o.status);
 const explanations={Placed:'Waiting for the owner to accept your order. Packing and delivery will start only after confirmation.',Confirmed:'The shop is preparing your order.',Shipped:'Your package has been dispatched.','Out for delivery':'The delivery partner is on the way.','Delivery failed':'The delivery attempt was unsuccessful. See the latest update below.',Delivered:'Your order has been marked delivered.',Cancelled:'This order was cancelled. Stock was restored.'};
 return `<article class="card order-card"><div class="row order-heading"><div><small>${esc(new Date(o.created*1000).toLocaleString())}</small><h3>${esc(o.id)}</h3></div><span class="status-pill status-${o.status.toLowerCase().replaceAll(' ','-')}">${o.status==='Placed'?'Awaiting owner confirmation':esc(o.status)}</span><strong>${money(o.total_paise)}</strong></div>${o.status==='Cancelled'?'<p class="cancelled-note">Order cancelled</p>':`<ol class="order-progress" aria-label="Order progress">${steps.map((step,i)=>`<li class="${i<=index?'complete':''}" ${i===index?'aria-current="step"':''}><span>${i<index?'✓':i+1}</span>${step}</li>`).join('')}</ol>`}<p class="muted">${explanations[o.status]}</p><p class="payment-status"><strong>Payment:</strong> ${esc(o.payment_method||'COD')} · ${esc(o.payment_status||'Pay on delivery')}${o.payment_reference?`<br><small>Demo reference: ${esc(o.payment_reference)}</small>`:''}</p>${o.status==='Cancelled'&&o.payment_method==='Online demo'?'<p class="notice">Demo cancellation only. No real payment or refund has occurred.</p>':''}<div class="order-items">${o.items.map(i=>`<div class="summary-line"><span>${esc(i.name)} <small>× ${i.quantity}</small></span><strong>${money(i.price_paise*i.quantity)}</strong></div>`).join('')}</div>${afterSalesMarkup(o,isAdmin,isDriver)}<details><summary>Delivery details & updates</summary><div class="order-details"><h4>Deliver to</h4><p>${esc(o.name)} · ${esc(o.phone)}</p><p>${esc(o.address)}</p>${manager?`<p>${esc(o.email)}</p>`:''}<p><strong>Courier:</strong> ${esc(o.courier||'Not assigned yet')}</p><p><strong>Tracking reference:</strong> ${esc(o.tracking||'Not available yet')}</p>${o.eta?`<p><strong>Estimated delivery:</strong> ${esc(o.eta)}</p>`:''}<h4>Delivery history</h4><ul class="delivery-history">${(o.history||[{status:o.status,note:'Current order status',at:o.created,actor:'Shop'}]).slice().reverse().map(h=>`<li><strong>${esc(h.status)}</strong> <small>${esc(new Date(h.at*1000).toLocaleString())} · ${esc(h.actor)}</small><p>${esc(h.note)}</p></li>`).join('')}</ul><hr><p class="summary-line"><span>Items subtotal</span><strong>${money(subtotal)}</strong></p><p class="summary-line"><span>Delivery fee</span><strong>${money(o.total_paise-subtotal)}</strong></p><p class="summary-line"><span>Total</span><strong>${money(o.total_paise)}</strong></p></div></details>${isAdmin&&o.status==='Placed'?`<div class="confirmation-box"><strong>New order · Your approval is required</strong><p>Review the products and delivery address. Delivery is locked until you confirm.</p><div class="row"><button data-confirm-order="${esc(o.id)}">Confirm order</button><button class="danger" data-reject-order="${esc(o.id)}">Reject order</button></div></div>`:manager&&o.status!=='Cancelled'?`<div class="row order-actions"><button data-delivery="${esc(o.id)}">${isAdmin?'Manage delivery':'Update delivery status'}</button>${isAdmin?`<span class="muted">${o.assigned_to?'Assigned to '+esc(o.assigned_to):'No delivery partner assigned'}</span>`:''}</div>`:''}</article>`;}).join('')||`<div class="card"><h3>${list.length?'No matching orders':isDriver?'No deliveries assigned':'No orders yet'}</h3><p>${list.length?'Try another search or status.':isDriver?'The owner can assign an order to delivery@demo.com from Manage delivery.':'Place a demo order to see it here.'}</p></div>`;
 document.querySelectorAll('[data-confirm-order]').forEach(b=>b.onclick=()=>orderDecision(list.find(o=>o.id===b.dataset.confirmOrder),true));
 document.querySelectorAll('[data-reject-order]').forEach(b=>b.onclick=()=>orderDecision(list.find(o=>o.id===b.dataset.rejectOrder),false));
 bindAfterSales();
 document.querySelectorAll('[data-delivery]').forEach(b=>b.onclick=()=>deliveryForm(list.find(o=>o.id===b.dataset.delivery)));
 };
 document.querySelector('#back').onclick=isDriver?action(orders):action(shop);document.querySelector('#orderSearch').oninput=draw;document.querySelector('#orderStatus').onchange=draw;draw();
}
function deliveryForm(o){
 if(o.status==='Placed'||o.status==='Cancelled'){message('Delivery is unavailable until the owner confirms the order.');return;}
 const isOwner=user.role==='admin',allowed={Placed:['Confirmed','Cancelled'],Confirmed:['Shipped','Cancelled'],Shipped:['Out for delivery','Delivered','Delivery failed'],'Out for delivery':['Delivered','Delivery failed'],'Delivery failed':['Out for delivery'],Delivered:[],Cancelled:[]};
 const choices=(allowed[o.status]||[]).filter(s=>isOwner||['Shipped','Out for delivery','Delivered','Delivery failed'].includes(s));
 view.innerHTML=`<section class="card"><h2>Update delivery</h2><h3>${esc(o.id)}</h3><p>Current status: <strong>${esc(o.status)}</strong></p><form id="deliveryForm">${isOwner?`<label>Assign delivery partner<select name="assigned_to"><option value="">Owner manages delivery</option><option value="delivery@demo.com" ${o.assigned_to==='delivery@demo.com'?'selected':''}>Demo delivery partner · delivery@demo.com</option></select></label>`:''}<label>Order / delivery status<select name="status"><option value="${esc(o.status)}">${esc(o.status)} (current)</option>${choices.map(s=>`<option>${s}</option>`).join('')}</select></label><label>Courier / delivery service<input name="courier" maxlength="100" placeholder="Shop delivery, courier name…" value="${esc(o.courier)}"></label><label>Tracking reference<input name="tracking" maxlength="100" value="${esc(o.tracking)}"></label><label>Estimated delivery date<input name="eta" type="date" value="${esc(o.eta)}"></label><label>Delivery update / note<textarea name="note" required minlength="3" maxlength="500" placeholder="e.g. Dispatched from shop, delivery expected tomorrow"></textarea></label><p class="muted">Customers can see this update in My Orders. This demo does not sync with an external courier system.</p><button>Save delivery update</button> <button id="cancelDelivery" type="button" class="secondary">Back</button></form></section>`;
 document.querySelector('#cancelDelivery').onclick=action(orders);
 document.querySelector('#deliveryForm').onsubmit=action(async e=>{const body=Object.fromEntries(new FormData(e.target));if(body.note.trim().length<3)throw Error('Add a short delivery update.');await api((isOwner?'/admin/orders/':'/delivery/orders/')+o.id,'PUT',body);message('Delivery updated. The customer can see the new status and note.');await orders();});
}

(async()=>{try{user=await api('/auth/me');}catch{}restoreCart();navigation();await shop();if(new URLSearchParams(location.search).has('login'))login();})().catch(e=>message(e.message));

document.querySelector('#customerSignIn').onclick=()=>{if(adminPath){location.href='/?login=customer';return;}login();};
document.querySelector('#ownerSignIn').onclick=()=>{if(!adminPath){location.href='/?portal=admin&login=owner';return;}login();};



document.querySelector('#deliverySignIn').onclick=()=>{if(!deliveryPath){location.href='/?portal=delivery&login=delivery';return;}login();};

function orderDecision(order,accept){
 view.innerHTML=`<section class="card decision-panel"><h2>${accept?'Confirm':'Reject'} order</h2><h3>${esc(order.id)}</h3><p>${esc(order.name)} · ${esc(order.phone)}</p><p>${esc(order.address)}</p>${order.items.map(i=>`<p>${esc(i.name)} × ${i.quantity}</p>`).join('')}<p class="price">${money(order.total_paise)}</p><p class="notice">${accept?'Accepting this order allows packing and delivery to proceed.':'Rejecting this order restores its reserved stock. No real refund is processed by this demo.'}</p><div class="row"><button id="commitOrderDecision" class="${accept?'':'danger'}">${accept?'Yes, confirm order':'Yes, reject order'}</button><button id="cancelOrderDecision" class="secondary">Go back</button></div></section>`;
 document.querySelector('#cancelOrderDecision').onclick=action(orders);
 document.querySelector('#commitOrderDecision').onclick=action(async()=>{await api('/admin/orders/'+order.id,'PUT',{status:accept?'Confirmed':'Cancelled',note:accept?'Owner accepted the order. Packing and delivery may now proceed.':'Owner rejected the order before confirmation.'});await orders();message(accept?'Order confirmed. Delivery is now unlocked.':'Order rejected. Reserved stock restored.');});
}
function afterSalesMarkup(order,isAdmin,isDriver){
 if(isDriver)return '';
 const requests=(state.returns||[]).filter(r=>r.order_id===order.id);
 return `<section class="after-sales"><h4>Returns & reviews</h4>${order.items.map(i=>{const request=requests.find(r=>r.product_id===i.product_id),review=(state.reviews||[]).find(r=>r.product_id===i.product_id&&r.email.toLowerCase()===order.email.toLowerCase());return `<div class="after-sales-item"><strong>${esc(i.name)}</strong><p class="policy-tag">${returnLabel(i)}</p>${request?`<div class="return-request"><p><strong>Return ${esc(request.status.toLowerCase())}</strong> · ${esc(request.id)}</p><p>${esc(request.reason)}</p>${request.notes?`<p>Shop response: ${esc(request.notes)}</p>`:''}${request.status==='Received'?'<p class="muted">Item received by shop. Any real refund must be handled separately.</p>':''}${isAdmin&&['Requested','Approved'].includes(request.status)?`<button class="secondary" data-manage-return="${esc(request.id)}">Manage return</button>`:''}</div>`:!isAdmin&&canReturn(order,i)?`<button class="secondary" data-request-return="${esc(order.id)}" data-product="${i.product_id}">Request return</button>`:i.returnable&&order.status==='Delivered'?'<p class="muted">Return window closed or delivery date unavailable.</p>':''}${!isAdmin&&order.status==='Delivered'?` <button class="secondary" data-write-review="${esc(order.id)}" data-product="${i.product_id}">${review?'Edit your review':'Write a review'}</button>`:''}<button class="review-link" data-order-reviews="${i.product_id}">View product reviews</button></div>`;}).join('')}</section>`;
}
function bindAfterSales(){
 document.querySelectorAll('[data-request-return]').forEach(b=>b.onclick=()=>returnForm(b.dataset.requestReturn,+b.dataset.product));
 document.querySelectorAll('[data-manage-return]').forEach(b=>b.onclick=()=>manageReturnForm(b.dataset.manageReturn));
 document.querySelectorAll('[data-write-review]').forEach(b=>b.onclick=()=>reviewForm(b.dataset.writeReview,+b.dataset.product));
 document.querySelectorAll('[data-order-reviews]').forEach(b=>b.onclick=action(()=>reviewsView(+b.dataset.orderReviews)));
}
function returnForm(orderId,productId){
 const order=state.orders.find(o=>o.id===orderId),item=order?.items.find(i=>i.product_id===productId);
 if(!order||!item||!canReturn(order,item)){message('This item is not eligible for return.');return;}
 const deadline=new Date((order.delivered_at+(item.return_days||7)*86400)*1000).toLocaleDateString();
 view.innerHTML=`<section class="card"><h2>Request a return</h2><h3>${esc(item.name)}</h3><p>${esc(order.id)} · Quantity ${item.quantity}</p><p class="policy-tag">${returnLabel(item)} · Request by ${esc(deadline)}</p><form id="returnForm"><label>Why do you want to return this item?<textarea name="reason" required minlength="5" maxlength="1000" placeholder="Describe the issue, such as damaged, faulty, or wrong item"></textarea></label><p class="muted">The owner will review your request. Return approval does not automatically issue a refund.</p><button>Submit return request</button> <button type="button" id="cancelReturn" class="secondary">Cancel</button></form></section>`;
 document.querySelector('#cancelReturn').onclick=action(orders);document.querySelector('#returnForm').onsubmit=action(async e=>{await api('/returns','POST',{order_id:orderId,product_id:productId,reason:new FormData(e.target).get('reason')});await orders();message('Return request submitted. Waiting for the owner to review it.');});
}
function manageReturnForm(id){
 const r=state.returns.find(r=>r.id===id);if(!r)return;
 view.innerHTML=`<section class="card"><h2>Manage return</h2><h3>${esc(r.name)}</h3><p>${esc(r.id)} · ${esc(r.status)}</p><p>Customer reason: ${esc(r.reason)}</p><form id="manageReturnForm"><label>Decision<select name="status">${(r.status==='Requested'?['Approved','Rejected']:['Received']).map(s=>`<option value="${s}">${s==='Received'?'Item received — restore stock':s}</option>`).join('')}</select></label><label>Message to customer<textarea name="notes" required minlength="3" maxlength="1000" placeholder="Add return instructions or explain your decision"></textarea></label><p class="notice">Mark an approved return as received only after the item comes back. Stock is restored once. This demo does not issue real refunds.</p><button>Save return update</button> <button type="button" id="cancelManageReturn" class="secondary">Back</button></form></section>`;
 document.querySelector('#cancelManageReturn').onclick=action(orders);document.querySelector('#manageReturnForm').onsubmit=action(async e=>{await api('/admin/returns/'+r.id,'PUT',Object.fromEntries(new FormData(e.target)));await orders();message('Return request updated.');});
}
async function reviewsView(productId){
 const product=state.products.find(p=>p.id===productId),reviews=await api('/reviews/'+productId),eligible=user&&state.orders.find(o=>o.email.toLowerCase()===user.email.toLowerCase()&&o.status==='Delivered'&&o.items.some(i=>i.product_id===productId));
 view.innerHTML=`<h2>Customer reviews</h2><h3>${esc(product?.name||'Product')}</h3><p class="price">${ratingSummary(productId)}</p><div class="row"><button id="reviewsBack" class="secondary">Back to shop</button>${eligible?'<button id="addReview">Write / edit your review</button>':'<span class="muted">Reviews can be written after delivery by customers who purchased this item.</span>'}</div><br>${reviews.map(r=>`<article class="card"><div class="row"><strong>${esc(r.display_name)}</strong><span class="brand-tag">Verified purchase</span></div><p class="stars" aria-label="${r.rating} out of 5 stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</p><small>${esc(new Date(r.updated*1000).toLocaleDateString())}</small><p class="review-text">${esc(r.text)}</p>${r.photo?`<img class="review-photo" src="${esc(r.photo)}" alt="Customer photo for ${esc(product?.name||'this product')}">`:''}</article>`).join('')||'<div class="card"><h3>No reviews yet</h3><p>Be the first to share your experience after receiving this product.</p></div>'}`;
 document.querySelector('#reviewsBack').onclick=action(shop);if(eligible)document.querySelector('#addReview').onclick=()=>reviewForm(eligible.id,productId);
}
function reviewForm(orderId,productId){
 const order=state.orders.find(o=>o.id===orderId&&o.email.toLowerCase()===user?.email.toLowerCase()&&o.status==='Delivered'),item=order?.items.find(i=>i.product_id===productId);
 if(!order||!item){message('You can review this item after your order is delivered.');return;}
 const existing=state.reviews.find(r=>r.product_id===productId&&r.email.toLowerCase()===user.email.toLowerCase());let photo=existing?.photo||'',reading=false;
 view.innerHTML=`<section class="card"><h2>${existing?'Edit your':'Write a'} review</h2><h3>${esc(item.name)}</h3><span class="brand-tag">Verified purchase</span><form id="reviewForm"><label style="margin-top:18px">Public display name<input name="display_name" maxlength="60" required value="${esc(existing?.display_name||savedData().profile?.name||'Customer')}"></label><label>Rating<select name="rating" required><option value="">Choose a rating</option>${[5,4,3,2,1].map(n=>`<option value="${n}" ${existing?.rating===n?'selected':''}>${n} ${n===1?'star':'stars'} — ${'★'.repeat(n)}</option>`).join('')}</select></label><label>Your review<textarea name="text" required minlength="3" maxlength="2000" placeholder="What did you like or dislike about this product?">${esc(existing?.text)}</textarea></label><label>Add a photo (optional)<input type="file" id="reviewPhoto" accept="image/jpeg,image/png,image/webp"></label><small>JPG, PNG, WebP · up to 5 MB. Your name, text, rating, and photo will be visible to people browsing this demo.</small><div id="reviewPhotoPreview" class="photo-preview"></div><button id="removeReviewPhoto" type="button" class="secondary">Remove photo</button><p id="reviewPhotoStatus" role="status"></p><div class="row"><button id="publishReview">Publish review</button><button id="cancelReview" type="button" class="secondary">Cancel</button></div></form></section>`;
 const preview=()=>{document.querySelector('#reviewPhotoPreview').innerHTML=photo?`<img src="${esc(photo)}" alt="Review photo preview">`:'No review photo selected';document.querySelector('#removeReviewPhoto').hidden=!photo;};preview();
 document.querySelector('#reviewPhoto').onchange=async e=>{const file=e.target.files[0];if(!file)return;reading=true;document.querySelector('#publishReview').disabled=true;try{const image=await compressPhoto(file);if(image.length>800000)throw Error('Choose a smaller image.');photo=image;preview();document.querySelector('#reviewPhotoStatus').textContent='Photo ready to publish.';}catch(err){document.querySelector('#reviewPhotoStatus').textContent=err.message;}finally{reading=false;document.querySelector('#publishReview').disabled=false;}};
 document.querySelector('#removeReviewPhoto').onclick=()=>{photo='';document.querySelector('#reviewPhoto').value='';preview();};document.querySelector('#cancelReview').onclick=action(orders);
 document.querySelector('#reviewForm').onsubmit=action(async e=>{if(reading)throw Error('Wait for the photo to finish.');const f=Object.fromEntries(new FormData(e.target));await api('/reviews','POST',{order_id:orderId,product_id:productId,display_name:f.display_name,rating:+f.rating,text:f.text,photo});message('Your review is published and visible to shoppers.');await reviewsView(productId);});
}

document.querySelector('main > .card').remove();
const previewNotice=document.createElement('div');previewNotice.className='notice';previewNotice.innerHTML='<strong>Temporary preview · No email needed</strong><p>Sample data is saved only in this browser. Products, orders and payments here do not affect the real shop.</p><a href="/?portal=customer">Customer portal</a> · <a href="/?portal=admin">Owner portal</a> · <a href="/?portal=delivery">Delivery portal</a> · <a href="/?mode=live">Open real Supabase shop</a>';document.querySelector('main')?.prepend(previewNotice) || document.body.prepend(previewNotice);
